// ancient-depths — залы чозо in E фригийский (0 1 3 5 7 8 10), 91 BPM. Generated by MathMusic
// (style prime, seed 1): landing site → artifact → frozen halls → ruins → scan → the hunt → impact crater → silence.
// Themes: A — Frozen Halls (ледяные залы) (recomposed), B — Phazon (фазон) (ornamented); the bridge melody is newly
// composed on the rhythm of a theme from synthwave. Computed parts: an improvised solo, a counter-melody from the chords, a run up to the dominant in every build-up, the theme at half speed in the outro.
// It is an ordinary song file: change anything; the melodies can be drawn in the piano roll (P).
// x is time in beats; n counts semitones from C4 (MIDI 60).
import { TAU, delay, exp, filter, floor, hz, mod, noise, osc, reverb, sin, smooth } from '../src/engine.js'
import {
  VOWELS, arrangement, chorus, clankTone, crashCymbal, flute, hash, hatDrum, improvise, kickDrum, monoSynth, notesAt, pan, pluckTone, poly, snareDrum, strings, taikoDrum, trigger, voice,
} from '../src/instruments.js'

const SECTIONS = [[0,"landing site"],[16,"artifact"],[48,"frozen halls"],[80,"ruins"],[112,"scan"],[144,"the hunt"],[160,"impact crater"],[224,"silence"]]
const END = 240
const part = arrangement(SECTIONS)
const is = (x, ...names) => names.includes(part(x).name)
const C4 = 440 * 2 ** (-9 / 12) // 261.63 Hz, exact equal temperament
const SW = 0.5 // the off-beat eighth lands at 0.5 of the beat
const ROLE = [[0,"intro",0],[16,"theme",2],[48,"bridge",1],[80,"themeB",2],[112,"solo",2],[144,"build",2],[160,"final",3],[224,"outro",0]] // [start, role, energy 0–3] per section
const sectionOf = x => { let s = ROLE[0]; for (const r of ROLE) if (r[0] <= x) s = r; return s }
const energy = x => (x < END ? sectionOf(x)[2] : -1)
const role = x => (x < END ? sectionOf(x)[1] : 'end')

